ALTER TYPE "LedgerTransactionType" ADD VALUE 'EXPENSE';ALTER TYPE "LedgerTransactionType" ADD VALUE 'DEPOSIT';ALTER TYPE "LedgerTransactionType" ADD VALUE 'WITHDRAWAL';ALTER TYPE "LedgerTransactionType" ADD VALUE 'OPENING_BALANCE';ALTER TYPE "LedgerTransactionType" ADD VALUE 'CLOSING_BALANCE';
CREATE TYPE "CommissionKind" AS ENUM ('PERCENTAGE','FIXED','TIERED');CREATE TYPE "CommissionScope" AS ENUM ('TENANT','BRANCH','MERCHANT','GAME','BET_TYPE');CREATE TYPE "CashSessionStatus" AS ENUM ('OPEN','CLOSED');CREATE TYPE "CashMovementType" AS ENUM ('CASH_IN','CASH_OUT','EXPENSE','DEPOSIT','WITHDRAWAL','ADJUSTMENT');CREATE TYPE "BalanceDifference" AS ENUM ('BALANCED','SHORT','OVER');
CREATE TABLE "CommissionRule"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"scope" "CommissionScope" NOT NULL,"scopeId" UUID,"kind" "CommissionKind" NOT NULL,"percentage" NUMERIC(9,6),"fixedAmount" NUMERIC(19,4),"tiers" JSONB,"priority" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"startsAt" TIMESTAMPTZ NOT NULL,"endsAt" TIMESTAMPTZ,CHECK(("kind"='PERCENTAGE' AND "percentage">=0) OR ("kind"='FIXED' AND "fixedAmount">=0) OR ("kind"='TIERED' AND "tiers" IS NOT NULL)));
CREATE TABLE "CommissionTransaction"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketId" UUID NOT NULL UNIQUE REFERENCES "Ticket"("id") ON DELETE RESTRICT,"merchantId" UUID NOT NULL REFERENCES "MerchantAccount"("id") ON DELETE RESTRICT,"ruleId" UUID REFERENCES "CommissionRule"("id") ON DELETE SET NULL,"baseAmount" NUMERIC(19,4) NOT NULL,"commissionAmount" NUMERIC(19,4) NOT NULL,"ledgerTransactionId" UUID NOT NULL UNIQUE REFERENCES "LedgerTransaction"("id") ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "CashSession"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"merchantId" UUID NOT NULL REFERENCES "MerchantAccount"("id") ON DELETE RESTRICT,"openedById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"closedById" UUID REFERENCES "User"("id") ON DELETE RESTRICT,"status" "CashSessionStatus" NOT NULL DEFAULT 'OPEN',"openingCash" NUMERIC(19,4) NOT NULL,"expectedCash" NUMERIC(19,4),"actualCash" NUMERIC(19,4),"difference" NUMERIC(19,4),"differenceStatus" "BalanceDifference","openedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"closedAt" TIMESTAMPTZ,CHECK("openingCash">=0));
CREATE UNIQUE INDEX "one_open_cash_session" ON "CashSession"("tenantId","merchantId") WHERE "status"='OPEN';
CREATE TABLE "CashMovement"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"sessionId" UUID NOT NULL REFERENCES "CashSession"("id") ON DELETE RESTRICT,"type" "CashMovementType" NOT NULL,"amount" NUMERIC(19,4) NOT NULL,"reason" VARCHAR(300) NOT NULL,"createdById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"idempotencyKey" VARCHAR(100) NOT NULL,"ledgerTransactionId" UUID NOT NULL UNIQUE REFERENCES "LedgerTransaction"("id") ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","idempotencyKey"),CHECK("amount">0));
CREATE INDEX "commission_rule_lookup" ON "CommissionRule"("tenantId","scope","scopeId","active","priority");CREATE INDEX "commission_merchant_time" ON "CommissionTransaction"("tenantId","merchantId","createdAt" DESC);CREATE INDEX "cash_session_lookup" ON "CashSession"("tenantId","merchantId","status");CREATE INDEX "cash_movement_time" ON "CashMovement"("sessionId","createdAt");
ALTER TABLE "CommissionRule" ENABLE ROW LEVEL SECURITY;ALTER TABLE "CommissionTransaction" ENABLE ROW LEVEL SECURITY;ALTER TABLE "CashSession" ENABLE ROW LEVEL SECURITY;ALTER TABLE "CashMovement" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_commission_rule_isolation ON "CommissionRule" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_commission_tx_isolation ON "CommissionTransaction" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_cash_session_isolation ON "CashSession" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_cash_movement_isolation ON "CashMovement" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
